/**
 * Private file storage for member photos and the gym logo (backend design
 * §12). Files live outside any public web root and are served only through
 * authenticated API routes. Keys are generated by the server, never taken
 * from user input.
 */

import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";

const KEY_RE = /^(members|logo)\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(jpg|png)$/;

export class FileStorage {
  private readonly root: string;

  constructor(dir: string) {
    this.root = resolve(dir);
  }

  /** New key for an object owned by `ownerId` (a member id, or the logo slot). */
  newKey(
    kind: "members" | "logo",
    ownerId: string,
    extension: "jpg" | "png",
  ): string {
    return `${kind}/${ownerId}/${randomUUID()}.${extension}`;
  }

  private pathFor(key: string): string {
    if (!KEY_RE.test(key)) throw new Error(`Invalid storage key: ${key}`);
    const path = resolve(this.root, key);
    if (!path.startsWith(this.root + sep))
      throw new Error(`Storage key escapes the root: ${key}`);
    return path;
  }

  /** Writes atomically (temp file + rename) so readers never see a partial image. */
  async put(key: string, data: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true, mode: 0o700 });
    const temp = join(dirname(path), `.${randomUUID()}.tmp`);
    await writeFile(temp, data, { mode: 0o600 });
    await rename(temp, path);
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.pathFor(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }
}
